package rec

import (
	"sort"
	"unicode/utf8"
)

// This file checks whether a string is in Unicode Normalization Form C.
//
// The specification (3.6) requires every string to be NFC, and the decoder
// must reject anything else. The standard library has no normalization
// support and golang.org/x/text is not an allowed dependency, so the check
// is implemented here directly from the Unicode Character Database
// (tables in nfc_tables.go, generated by nfc_tables_gen.go).
//
// The check is exact: a string is NFC if and only if normalizing it (full
// canonical decomposition, canonical ordering, canonical composition as in
// UAX #15) yields the same string. The NFC_Quick_Check property is used
// only as a fast path: a string whose code points all have
// NFC_Quick_Check=Yes and whose combining marks are in canonical order is
// NFC without further work, and a code point with NFC_Quick_Check=No makes
// the string non-NFC without further work. A quick check of "Maybe" is
// resolved by running the full normalization and comparing.
//
// The package never normalizes on behalf of a caller. Strings that are not
// NFC are rejected, so that encoding and decoding stay byte-identical.

type runeRange struct {
	lo, hi rune
	v      uint8
}

// decompEntry is a direct canonical decomposition cp -> a b (b == 0 for a
// singleton decomposition cp -> a).
type decompEntry struct {
	cp, a, b rune
}

// compEntry is a primary composite: a + b composes to c.
type compEntry struct {
	a, b, c rune
}

const (
	qcYes   uint8 = 0
	qcNo    uint8 = 1
	qcMaybe uint8 = 2
)

// Hangul syllable constants from the Unicode Standard, chapter 3.12.
const (
	hangulSBase  = 0xAC00
	hangulLBase  = 0x1100
	hangulVBase  = 0x1161
	hangulTBase  = 0x11A7
	hangulLCount = 19
	hangulVCount = 21
	hangulTCount = 28
	hangulNCount = hangulVCount * hangulTCount
	hangulSCount = hangulLCount * hangulNCount
)

// maxDecompDepth bounds the recursion of canonical decomposition. The
// deepest chain in the Unicode database is four code points.
const maxDecompDepth = 8

func lookupRange(tab []runeRange, r rune) uint8 {
	i := sort.Search(len(tab), func(i int) bool { return tab[i].hi >= r })
	if i < len(tab) && tab[i].lo <= r {
		return tab[i].v
	}
	return 0
}

func combiningClass(r rune) uint8 { return lookupRange(cccRanges, r) }

func quickCheck(r rune) uint8 { return lookupRange(nfcQCRanges, r) }

// composePair returns the primary composite of a and b, if one exists.
func composePair(a, b rune) (rune, bool) {
	// Hangul L+V and LV+T.
	if a >= hangulLBase && a < hangulLBase+hangulLCount &&
		b >= hangulVBase && b < hangulVBase+hangulVCount {
		l := a - hangulLBase
		v := b - hangulVBase
		return hangulSBase + (l*hangulVCount+v)*hangulTCount, true
	}
	if a >= hangulSBase && a < hangulSBase+hangulSCount &&
		(a-hangulSBase)%hangulTCount == 0 &&
		b > hangulTBase && b < hangulTBase+hangulTCount {
		return a + (b - hangulTBase), true
	}
	i := sort.Search(len(compPairs), func(i int) bool {
		p := compPairs[i]
		return p.a > a || (p.a == a && p.b >= b)
	})
	if i < len(compPairs) && compPairs[i].a == a && compPairs[i].b == b {
		return compPairs[i].c, true
	}
	return 0, false
}

// decompose appends the full canonical decomposition of r to out.
func decompose(out []rune, r rune, depth int) []rune {
	if depth > maxDecompDepth {
		// Cannot happen with the generated tables; keeps the recursion
		// bounded regardless of table contents.
		return append(out, r)
	}
	if r >= hangulSBase && r < hangulSBase+hangulSCount {
		s := r - hangulSBase
		out = append(out, hangulLBase+s/hangulNCount, hangulVBase+(s%hangulNCount)/hangulTCount)
		if t := s % hangulTCount; t != 0 {
			out = append(out, hangulTBase+t)
		}
		return out
	}
	i := sort.Search(len(decompTable), func(i int) bool { return decompTable[i].cp >= r })
	if i < len(decompTable) && decompTable[i].cp == r {
		e := decompTable[i]
		out = decompose(out, e.a, depth+1)
		if e.b != 0 {
			out = decompose(out, e.b, depth+1)
		}
		return out
	}
	return append(out, r)
}

// normalizeNFC returns the NFC form of the code points in rs.
func normalizeNFC(rs []rune) []rune {
	// 1. Full canonical decomposition.
	d := make([]rune, 0, len(rs)+4)
	for _, r := range rs {
		d = decompose(d, r, 0)
	}
	// 2. Canonical ordering: stable sort of every run of non-starters by
	// combining class.
	for i := 0; i < len(d); {
		if combiningClass(d[i]) == 0 {
			i++
			continue
		}
		j := i
		for j < len(d) && combiningClass(d[j]) != 0 {
			j++
		}
		run := d[i:j]
		sort.SliceStable(run, func(a, b int) bool { return combiningClass(run[a]) < combiningClass(run[b]) })
		i = j
	}
	// 3. Canonical composition.
	out := d[:0]
	starter := -1
	var lastCCC uint8
	for _, c := range d {
		ccc := combiningClass(c)
		if starter >= 0 {
			// c is blocked from the starter if a code point lies between
			// them with combining class zero or at least ccc. Everything
			// between has a non-zero class (a zero would have become the
			// new starter), and after ordering the largest of those is
			// the class of the last appended code point.
			between := len(out)-1 > starter
			blocked := between && lastCCC >= ccc
			if !blocked {
				if comp, ok := composePair(out[starter], c); ok {
					out[starter] = comp
					continue
				}
			}
		}
		if ccc == 0 {
			starter = len(out)
		}
		out = append(out, c)
		lastCCC = ccc
	}
	return out
}

// isNFC reports whether s is valid UTF-8 in Normalization Form C. It does
// not check for NUL bytes; the caller does.
func isNFC(s string) bool {
	if !utf8.ValidString(s) {
		return false
	}
	var (
		prevCCC uint8
		slow    bool
	)
	for _, r := range s {
		if r < 0x300 {
			// Below U+0300 there are no combining marks and no quick-check
			// exceptions.
			prevCCC = 0
			continue
		}
		switch quickCheck(r) {
		case qcNo:
			return false
		case qcMaybe:
			slow = true
		}
		ccc := combiningClass(r)
		if ccc != 0 && prevCCC > ccc {
			return false // combining marks out of canonical order
		}
		prevCCC = ccc
	}
	if !slow {
		return true
	}
	// A quick check of Maybe: normalize and compare.
	rs := []rune(s)
	n := normalizeNFC(append([]rune(nil), rs...))
	if len(n) != len(rs) {
		return false
	}
	for i := range rs {
		if rs[i] != n[i] {
			return false
		}
	}
	return true
}

// validUTF8 reports whether s is valid UTF-8. It lets checkValue tell a
// malformed string from a well-formed one that is not normalized.
func validUTF8(s string) bool { return utf8.ValidString(s) }
